sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var taskBuilder = new CreateSamValueBuildertask();
        var result = taskBuilder.createTasks(); // Get task names and properties

        // Log processed properties to console
        gs.info('Processed Properties: ' + JSON.stringify(result.processedProperties));

        response.setStatus(200);
        response.setBody({
            status: "success",
            message: "Tasks created successfully.",
            processed_properties: result.processedProperties.length ? result.processedProperties : ["No properties processed."]
        });

    } catch (error) {
        gs.error("Error executing CreateSamValueBuildertask: " + error.message);
        response.setStatus(500);
        response.setBody({
            status: "error",
            message: "An error occurred while creating tasks: " + error.message
        });
    }
})(request, response);
